// Generated from the project-root HTML files by npm run sync:game.
export const GAME_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, user-scalable=no, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#111827\">\n\n<title>Serpent Run</title>\n<style>\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body {\n    width: 100%;\n    height: 100%;\n    overflow: hidden;\n    background: #020617;\n    color: #e0f2fe;\n    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;\n    user-select: none;\n    -webkit-user-select: none;\n    touch-action: none;\n  }\n  #game-canvas {\n    display: block;\n    width: 100%;\n    height: 100%;\n    position: absolute;\n    top: 0;\n    left: 0;\n  }\n  #hud {\n    position: absolute;\n    top: max(12px, env(safe-area-inset-top));\n    left: max(12px, env(safe-area-inset-left));\n    z-index: 10;\n    pointer-events: none;\n    display: none;\n    gap: 10px;\n    font-size: 14px;\n    text-shadow: 0 0 8px rgba(0,255,200,0.4);\n    flex-wrap: wrap;\n    align-items: center;\n  }\n  .hud-stat {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    background: rgba(4, 16, 36, 0.7);\n    padding: 6px 14px;\n    border-radius: 20px;\n    border: 1px solid rgba(0, 240, 255, 0.25);\n    backdrop-filter: blur(6px);\n  }\n  .hud-val {\n    font-weight: bold;\n    color: #38bdf8;\n  }\n  #mute-btn {\n    pointer-events: auto;\n    min-height: 44px;\n    background: rgba(4, 16, 36, 0.7);\n    border: 1px solid rgba(0, 240, 255, 0.25);\n    color: #e0f2fe;\n    padding: 6px 12px;\n    border-radius: 20px;\n    cursor: pointer;\n    font-size: 14px;\n    backdrop-filter: blur(6px);\n    transition: all 0.2s;\n  }\n  #pause-btn {\n    pointer-events: auto;\n    width: 44px;\n    height: 44px;\n    display: grid;\n    place-items: center;\n    background: rgba(4, 16, 36, 0.82);\n    border: 1px solid rgba(0, 240, 255, 0.35);\n    color: #e0f2fe;\n    border-radius: 50%;\n    cursor: pointer;\n    font-size: 18px;\n    backdrop-filter: blur(6px);\n  }\n  #mute-btn:hover {\n    border-color: #00f5ff;\n    color: #00f5ff;\n  }\n\n  /* Live Leaderboard */\n  #leaderboard {\n    position: absolute;\n    top: max(12px, env(safe-area-inset-top));\n    right: max(12px, env(safe-area-inset-right));\n    z-index: 10;\n    pointer-events: none;\n    display: none;\n    background: rgba(4, 16, 36, 0.75);\n    border: 1px solid rgba(56, 189, 248, 0.25);\n    border-radius: 14px;\n    padding: 10px 14px;\n    backdrop-filter: blur(8px);\n    min-width: 170px;\n    box-shadow: 0 4px 20px rgba(0,0,0,0.4);\n  }\n  .lb-title {\n    font-size: 11px;\n    text-transform: uppercase;\n    letter-spacing: 1.5px;\n    color: #94a3b8;\n    margin-bottom: 6px;\n    font-weight: bold;\n    text-align: center;\n  }\n  .lb-list {\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n  }\n  .lb-item {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    font-size: 13px;\n    padding: 3px 6px;\n    border-radius: 6px;\n  }\n  .lb-item.is-player {\n    background: rgba(0, 245, 255, 0.18);\n    border: 1px solid rgba(0, 245, 255, 0.4);\n    font-weight: bold;\n  }\n  .lb-left {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n  }\n  .lb-dot {\n    width: 8px;\n    height: 8px;\n    border-radius: 50%;\n  }\n  .lb-length {\n    color: #94a3b8;\n    font-size: 12px;\n  }\n  .lb-item.is-player .lb-length {\n    color: #38bdf8;\n  }\n\n  /* Menu Screen */\n  #menu-screen {\n    position: absolute;\n    inset: 0;\n    background: rgba(2, 6, 23, 0.88);\n    backdrop-filter: blur(10px);\n    z-index: 60;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    padding: 24px;\n  }\n  #menu-screen h1 {\n    font-size: 52px;\n    color: #00f5ff;\n    text-shadow: 0 0 30px rgba(0, 245, 255, 0.65), 0 0 10px rgba(255,255,255,0.8);\n    margin-bottom: 6px;\n    letter-spacing: 4px;\n  }\n  .menu-sub {\n    font-size: 16px;\n    color: #94a3b8;\n    margin-bottom: 30px;\n    letter-spacing: 1px;\n  }\n  .diff-selector {\n    margin-bottom: 24px;\n  }\n  .diff-label {\n    display: block;\n    color: #64748b;\n    font-size: 12px;\n    text-transform: uppercase;\n    letter-spacing: 2px;\n    margin-bottom: 10px;\n  }\n  .diff-btns {\n    display: flex;\n    gap: 12px;\n  }\n  .diff-btn {\n    background: rgba(15, 23, 42, 0.7);\n    border: 1px solid rgba(56, 189, 248, 0.3);\n    color: #94a3b8;\n    padding: 10px 24px;\n    border-radius: 24px;\n    font-size: 15px;\n    cursor: pointer;\n    transition: all 0.2s ease;\n    font-family: inherit;\n  }\n  .diff-btn:hover {\n    border-color: #00f5ff;\n    color: #f8fafc;\n  }\n  .diff-btn.active {\n    background: rgba(0, 245, 255, 0.2);\n    border-color: #00f5ff;\n    color: #00f5ff;\n    box-shadow: 0 0 16px rgba(0, 245, 255, 0.4);\n    font-weight: bold;\n  }\n  .menu-records {\n    color: #94a3b8;\n    font-size: 13px;\n    margin-bottom: 24px;\n  }\n  .menu-records span {\n    color: #facc15;\n    font-weight: bold;\n  }\n  .play-btn {\n    background: linear-gradient(135deg, #00f5ff, #0284c7);\n    color: #020617;\n    border: none;\n    padding: 14px 48px;\n    border-radius: 30px;\n    font-size: 20px;\n    font-weight: bold;\n    cursor: pointer;\n    box-shadow: 0 0 25px rgba(0, 245, 255, 0.5);\n    transition: all 0.2s ease;\n    font-family: inherit;\n    letter-spacing: 1px;\n  }\n  .play-btn:hover {\n    transform: scale(1.05);\n    box-shadow: 0 0 35px rgba(0, 245, 255, 0.75);\n  }\n  .menu-hint {\n    color: #64748b;\n    font-size: 13px;\n    margin-top: 30px;\n    line-height: 1.6;\n  }\n  .privacy-link {\n    color: #7dd3fc;\n    font-size: 13px;\n    margin-top: 18px;\n    text-decoration: underline;\n    text-underline-offset: 3px;\n  }\n\n  /* Pause Overlay */\n  #pause-overlay {\n    display: none;\n    position: absolute;\n    inset: 0;\n    background: rgba(2, 6, 23, 0.7);\n    backdrop-filter: blur(6px);\n    z-index: 55;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n  }\n  #pause-overlay h2 {\n    font-size: 38px;\n    color: #38bdf8;\n    text-shadow: 0 0 20px rgba(56, 189, 248, 0.5);\n    margin-bottom: 12px;\n  }\n\n  /* Game Over Overlay */\n  #overlay {\n    display: none;\n    position: absolute;\n    inset: 0;\n    background: rgba(2, 6, 23, 0.82);\n    backdrop-filter: blur(8px);\n    z-index: 50;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    padding: 24px;\n  }\n  #overlay h2 {\n    font-size: 42px;\n    color: #f43f5e;\n    text-shadow: 0 0 25px rgba(244, 63, 94, 0.6);\n    margin-bottom: 20px;\n    letter-spacing: 2px;\n  }\n  .score-card {\n    background: rgba(15, 23, 42, 0.85);\n    border: 1px solid rgba(56, 189, 248, 0.3);\n    border-radius: 16px;\n    padding: 20px 32px;\n    margin-bottom: 24px;\n    min-width: 280px;\n    box-shadow: 0 10px 30px rgba(0,0,0,0.5);\n  }\n  .score-row {\n    display: flex;\n    justify-content: space-between;\n    margin: 10px 0;\n    font-size: 16px;\n  }\n  .score-row .label { color: #94a3b8; }\n  .score-row .val { color: #38bdf8; font-weight: bold; }\n  .score-row .best { color: #facc15; font-weight: bold; }\n  .restart-hint {\n    color: #cbd5e1;\n    font-size: 16px;\n    animation: pulseHint 1.8s infinite ease-in-out;\n    cursor: pointer;\n  }\n  @keyframes pulseHint {\n    0%, 100% { opacity: 0.6; transform: scale(0.98); }\n    50% { opacity: 1; transform: scale(1.02); }\n  }\n  @media (max-width: 480px) {\n    #menu-screen { padding: 18px; }\n    #menu-screen h1 { font-size: clamp(30px, 9vw, 42px); letter-spacing: 2px; }\n    .menu-sub { font-size: 14px; margin-bottom: 20px; }\n    .diff-btn { padding: 10px 18px; }\n    .menu-hint { margin-top: 20px; }\n    #leaderboard { top: auto; bottom: max(12px, env(safe-area-inset-bottom)); }\n    #hud { right: max(12px, env(safe-area-inset-right)); gap: 6px; }\n    .hud-stat { padding: 6px 10px; font-size: 13px; }\n  }\n  @media (max-height: 560px) and (orientation: landscape) {\n    #menu-screen { justify-content: flex-start; overflow-y: auto; padding-block: 12px; touch-action: pan-y; }\n    #menu-screen h1 { font-size: 32px; margin-bottom: 2px; }\n    .menu-sub { margin-bottom: 10px; }\n    .diff-selector { margin-bottom: 10px; }\n    .menu-records { margin-bottom: 12px; }\n    .menu-hint { margin-top: 10px; }\n  }\n\n  /* Store-ready, restrained mobile interface */\n  :root { color-scheme: dark; }\n  html, body { background: #111827; color: #f3f4f6; }\n  #hud { text-shadow: none; gap: 8px; }\n  #stat-cycle { display: flex; }\n  #cycle-icon { color: #fcd34d; font-size: 16px; }\n  .hud-stat, #mute-btn, #pause-btn {\n    background: rgba(17, 24, 39, .92); border-color: rgba(255,255,255,.16);\n    color: #f3f4f6; box-shadow: 0 2px 8px rgba(0,0,0,.18); backdrop-filter: none;\n  }\n  .hud-val { color: #a7f3d0; }\n  #pause-btn { border-radius: 12px; }\n  #mute-btn { border-radius: 12px; }\n  #home-btn {\n    pointer-events: auto; width: 44px; height: 44px; display: grid; place-items: center;\n    background: rgba(17,24,39,.92); border: 1px solid rgba(255,255,255,.16); color: #f3f4f6;\n    border-radius: 12px; font-family: inherit; font-size: 20px; font-weight: 600; cursor: pointer;\n  }\n  #leaderboard { background: rgba(17,24,39,.9); border-color: rgba(255,255,255,.14); box-shadow: 0 2px 8px rgba(0,0,0,.15); backdrop-filter: none; }\n  .lb-item.is-player { background: rgba(16,185,129,.12); border-color: rgba(16,185,129,.35); }\n  .lb-item.is-player .lb-length { color: #a7f3d0; }\n  #menu-screen { background: #111827; backdrop-filter: none; }\n  #menu-screen h1 { color: #f9fafb; text-shadow: none; font-size: clamp(34px, 8vw, 50px); letter-spacing: 1px; }\n  .menu-sub { color: #9ca3af; letter-spacing: .2px; }\n  .diff-label { color: #9ca3af; letter-spacing: 1px; }\n  .diff-btn { background: #1f2937; border-color: #374151; color: #d1d5db; border-radius: 12px; min-height: 44px; }\n  .diff-btn.active { background: #064e3b; border-color: #10b981; color: #d1fae5; box-shadow: none; }\n  .play-btn { background: #059669; color: #fff; border-radius: 14px; min-height: 54px; box-shadow: none; letter-spacing: .2px; }\n  .play-btn:hover { transform: none; background: #047857; box-shadow: none; }\n  .menu-records span { color: #a7f3d0; }\n  .menu-hint { color: #9ca3af; }\n  .privacy-link { color: #a7f3d0; }\n  #pause-overlay, #overlay { background: rgba(17,24,39,.96); backdrop-filter: none; }\n  #pause-overlay h2, #overlay h2 { color: #f9fafb; text-shadow: none; }\n  .score-card { background: #1f2937; border-color: #374151; box-shadow: none; }\n  .score-row .val { color: #a7f3d0; }\n  .score-row .best { color: #fcd34d; }\n  .restart-hint { animation: none; }\n  @media (max-width: 480px) {\n    #leaderboard { min-width: 132px; padding: 8px 10px; }\n    #hud { gap: 5px; }\n    .hud-stat { padding: 6px 8px; }\n  }\n</style>\n</head>\n<body>\n\n<canvas id=\"game-canvas\"></canvas>\n\n<!-- HUD -->\n<div id=\"hud\">\n  <div class=\"hud-stat\" id=\"stat-cycle\" aria-live=\"polite\">\n    <span id=\"cycle-icon\" aria-hidden=\"true\">☼</span>\n    <span id=\"cycle-name\" class=\"hud-val\">Dawn</span>\n  </div>\n  <div class=\"hud-stat\">\n    <span>Time:</span>\n    <span id=\"stat-time\" class=\"hud-val\">00:00</span>\n  </div>\n  <div class=\"hud-stat\">\n    <span>Length:</span>\n    <span id=\"stat-length\" class=\"hud-val\">30</span>\n  </div>\n  <div class=\"hud-stat\">\n    <span>Rank:</span>\n    <span id=\"stat-rank\" class=\"hud-val\">#1</span>\n  </div>\n  <button id=\"pause-btn\" type=\"button\" aria-label=\"Pause game\" title=\"Pause game\">Ⅱ</button>\n  <button id=\"home-btn\" type=\"button\" aria-label=\"Return to home\" title=\"Home\">⌂</button>\n  <button id=\"mute-btn\" type=\"button\" aria-label=\"Toggle sound\" onclick=\"toggleMute()\">🔊</button>\n</div>\n\n<!-- Live Leaderboard -->\n<div id=\"leaderboard\">\n  <div class=\"lb-title\">Leaderboard</div>\n  <div class=\"lb-list\" id=\"lb-list\"></div>\n</div>\n\n<!-- Menu Start Screen -->\n<div id=\"menu-screen\">\n  <h1>SERPENT RUN</h1>\n  <div class=\"menu-sub\">A simple survival challenge</div>\n\n  <div class=\"diff-selector\">\n    <span class=\"diff-label\">Select Difficulty</span>\n    <div class=\"diff-btns\">\n      <button class=\"diff-btn\" data-diff=\"easy\" onclick=\"setDifficulty('easy')\">Easy</button>\n      <button class=\"diff-btn active\" data-diff=\"normal\" onclick=\"setDifficulty('normal')\">Normal</button>\n      <button class=\"diff-btn\" data-diff=\"hard\" onclick=\"setDifficulty('hard')\">Hard</button>\n    </div>\n  </div>\n\n  <div class=\"menu-records\">\n    Best Record (<span id=\"diff-name-label\">Normal</span>): Time: <span id=\"menu-best-time\">00:00</span> &bull; Length: <span id=\"menu-best-len\">30</span>\n  </div>\n\n  <button class=\"play-btn\" onclick=\"startGame()\">Play</button>\n\n  <div class=\"menu-hint\">\n    Touch and drag to steer &bull; Tap pause anytime<br>\n    Collect food, avoid other snakes, and survive\n  </div>\n  <a class=\"privacy-link\" href=\"privacy-policy.html\">Privacy Policy</a>\n</div>\n\n<!-- Pause Overlay -->\n<div id=\"pause-overlay\">\n  <h2>GAME PAUSED</h2>\n  <div class=\"restart-hint\">Press P or Space to Resume</div>\n</div>\n\n<!-- Game Over Overlay -->\n<div id=\"overlay\">\n  <h2>SERPENT DISSOLVED</h2>\n  <div class=\"score-card\">\n    <div class=\"score-row\">\n      <span class=\"label\">Survival Time:</span>\n      <span id=\"final-time\" class=\"val\">00:00</span>\n    </div>\n    <div class=\"score-row\">\n      <span class=\"label\">Best Time (<span id=\"card-diff-label\">Normal</span>):</span>\n      <span id=\"best-time\" class=\"best\">00:00</span>\n    </div>\n    <div class=\"score-row\">\n      <span class=\"label\">Final Length:</span>\n      <span id=\"final-length\" class=\"val\">30</span>\n    </div>\n    <div class=\"score-row\">\n      <span class=\"label\">Best Length:</span>\n      <span id=\"best-length\" class=\"best\">30</span>\n    </div>\n  </div>\n  <div class=\"restart-hint\">Press Enter or Tap to Restart</div>\n</div>\n\n<script>\n// ============================================================\n// §1  CONSTANTS & DIFFICULTY SPEEDS\n// ============================================================\nconst SPEED_CONFIGS = {\n  easy: 2.8,\n  normal: 3.6,\n  hard: 4.4\n};\n\nconst TURN_RATE = 0.075;\nconst SEGMENT_SPACING = 6;\nconst INITIAL_SEGMENTS = 22;\nconst HEAD_RADIUS = 9;\nconst FOOD_COUNT = 42;\nconst BOT_COUNT = 4;\nconst RESPAWN_DELAY_FRAMES = 180;\nconst MAX_PARTICLES = 18;\nconst CYCLE_DURATION_MS = 180000;\nconst CYCLE_PHASES = [\n  { name: 'Dawn', icon: '☼', top: [18, 48, 56], mid: [29, 93, 99], bot: [12, 36, 48], ray: [111, 206, 195], rays: 0.04, glow: 0.18, plankton: 0.02 },\n  { name: 'Midday', icon: '☀', top: [49, 120, 177], mid: [30, 151, 209], bot: [13, 55, 82], ray: [203, 233, 255], rays: 0.20, glow: 0.10, plankton: 0.00 },\n  { name: 'Dusk', icon: '◒', top: [87, 58, 113], mid: [180, 105, 85], bot: [55, 40, 71], ray: [255, 184, 133], rays: 0.07, glow: 0.24, plankton: 0.04 },\n  { name: 'Night', icon: '☾', top: [4, 8, 16], mid: [6, 14, 26], bot: [2, 5, 11], ray: [92, 117, 145], rays: 0.00, glow: 1.00, plankton: 0.24 }\n];\n\nconst FOOD_COLORS = [\n  { core: '#22d3ee', glow: 'rgba(34, 211, 238, 0.5)' },\n  { core: '#f43f5e', glow: 'rgba(244, 63, 94, 0.5)' },\n  { core: '#a855f7', glow: 'rgba(168, 85, 247, 0.5)' },\n  { core: '#10b981', glow: 'rgba(16, 185, 129, 0.5)' },\n  { core: '#fbbf24', glow: 'rgba(251, 191, 36, 0.5)' }\n];\n\nconst PALETTE_PLAYER = {\n  head: '#34d399',\n  bodyStart: '#10b981',\n  bodyEnd: '#047857',\n  scale: 'rgba(255, 255, 255, 0.12)',\n  glow: 'rgba(52, 211, 153, 0.72)',\n  eyeIris: '#047857',\n  eyePupil: '#064e3b',\n  tongue: '#f43f5e'\n};\n\nconst BOT_CONFIGS = [\n  {\n    name: 'Viper',\n    palette: {\n      head: '#10b981', bodyStart: '#059669', bodyEnd: '#047857',\n      scale: 'rgba(167, 243, 208, 0.35)', glow: 'rgba(16, 185, 129, 0.45)',\n      eyeIris: '#047857', eyePupil: '#022c22', tongue: '#f87171'\n    }\n  },\n  {\n    name: 'Hydra',\n    palette: {\n      head: '#c084fc', bodyStart: '#9333ea', bodyEnd: '#6b21a8',\n      scale: 'rgba(233, 213, 255, 0.35)', glow: 'rgba(192, 132, 252, 0.45)',\n      eyeIris: '#6b21a8', eyePupil: '#2e1065', tongue: '#fb7185'\n    }\n  },\n  {\n    name: 'Cobra',\n    palette: {\n      head: '#f59e0b', bodyStart: '#d97706', bodyEnd: '#b45309',\n      scale: 'rgba(254, 240, 138, 0.35)', glow: 'rgba(245, 158, 11, 0.45)',\n      eyeIris: '#b45309', eyePupil: '#451a03', tongue: '#f43f5e'\n    }\n  },\n  {\n    name: 'Abyss',\n    palette: {\n      head: '#f43f5e', bodyStart: '#e11d48', bodyEnd: '#9f1239',\n      scale: 'rgba(254, 205, 211, 0.35)', glow: 'rgba(244, 63, 94, 0.45)',\n      eyeIris: '#9f1239', eyePupil: '#4c0519', tongue: '#fda4af'\n    }\n  },\n  {\n    name: 'Phantom',\n    palette: {\n      head: '#f472b6', bodyStart: '#db2777', bodyEnd: '#9d174d',\n      scale: 'rgba(251, 207, 232, 0.35)', glow: 'rgba(244, 114, 182, 0.45)',\n      eyeIris: '#9d174d', eyePupil: '#500724', tongue: '#a78bfa'\n    }\n  },\n  {\n    name: 'Apex',\n    palette: {\n      head: '#a3e635', bodyStart: '#65a30d', bodyEnd: '#3f6212',\n      scale: 'rgba(217, 249, 157, 0.35)', glow: 'rgba(163, 230, 53, 0.45)',\n      eyeIris: '#3f6212', eyePupil: '#1a2e05', tongue: '#f43f5e'\n    }\n  }\n];\n\n// ============================================================\n// §2  STATE & AUDIO\n// ============================================================\nlet canvas = null;\nlet ctx = null;\nlet width = window.innerWidth;\nlet height = window.innerHeight;\nlet animFrame = 0;\nlet loopActive = false;\nconst cycleEpoch = performance.now();\nlet currentCycle = { ...CYCLE_PHASES[0], progress: 0, nightFactor: 0 };\n\nlet currentDifficulty = 'normal';\nlet isGameRunning = false;\nlet isPaused = false;\nlet isGameOver = false;\n\nlet gameStartTime = 0;\nlet pauseStartTime = 0;\nlet totalPausedDuration = 0;\nlet survivalSeconds = 0;\nlet shakeIntensity = 0;\n\nlet audioCtx = null;\nlet isMuted = false;\nlet ambientOsc1 = null;\nlet ambientOsc2 = null;\nlet ambientGain = null;\n\nconst foodOrbs = [];\nconst particles = [];\nconst plankton = [];\nconst bots = [];\n\nconst player = {\n  name: 'You',\n  isPlayer: true,\n  x: width / 2,\n  y: height / 2,\n  angle: -Math.PI / 2,\n  targetAngle: -Math.PI / 2,\n  speed: SPEED_CONFIGS.normal,\n  turnRate: TURN_RATE,\n  length: INITIAL_SEGMENTS,\n  segments: [],\n  palette: PALETTE_PLAYER,\n  tongueTimer: 0,\n  tongueProgress: 0,\n  growQueue: 0,\n  glowTrailTimer: 0,\n  alive: true,\n};\n\nconst keys = { left: false, right: false };\nconst mouse = { x: width / 2, y: height / 2, active: false };\n\nlet hudEl = null;\nlet lbEl = null;\nlet menuScreenEl = null;\nlet pauseOverlayEl = null;\nlet statTimeEl = null;\nlet statLengthEl = null;\nlet statRankEl = null;\nlet lbListEl = null;\nlet overlayEl = null;\nlet finalTimeEl = null;\nlet bestTimeEl = null;\nlet finalLengthEl = null;\nlet bestLengthEl = null;\nlet muteBtnEl = null;\nlet diffNameLabel = null;\nlet menuBestTime = null;\nlet menuBestLen = null;\nlet cardDiffLabel = null;\nlet cycleIconEl = null;\nlet cycleNameEl = null;\n\n// ============================================================\n// §3  AUDIO SYNTHESIS (NO EXTERNAL FILES)\n// ============================================================\n\nfunction initAudio() {\n  if (audioCtx) return;\n  try {\n    audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n\n    const filter = audioCtx.createBiquadFilter();\n    filter.type = 'lowpass';\n    filter.frequency.value = 140;\n\n    ambientGain = audioCtx.createGain();\n    ambientGain.gain.setValueAtTime(isMuted ? 0 : 0.035, audioCtx.currentTime);\n\n    ambientOsc1 = audioCtx.createOscillator();\n    ambientOsc1.type = 'sine';\n    ambientOsc1.frequency.value = 55;\n\n    ambientOsc2 = audioCtx.createOscillator();\n    ambientOsc2.type = 'sine';\n    ambientOsc2.frequency.value = 58.5;\n\n    ambientOsc1.connect(filter);\n    ambientOsc2.connect(filter);\n    filter.connect(ambientGain);\n    ambientGain.connect(audioCtx.destination);\n\n    ambientOsc1.start();\n    ambientOsc2.start();\n  } catch (_) {}\n}\n\nfunction playTone(freqStart, freqEnd, duration, type = 'sine', volume = 0.1) {\n  if (isMuted || !audioCtx) return;\n  try {\n    if (audioCtx.state === 'suspended') audioCtx.resume();\n    const osc = audioCtx.createOscillator();\n    const gain = audioCtx.createGain();\n    osc.type = type;\n    osc.frequency.setValueAtTime(freqStart, audioCtx.currentTime);\n    if (freqEnd !== freqStart) {\n      osc.frequency.exponentialRampToValueAtTime(Math.max(20, freqEnd), audioCtx.currentTime + duration);\n    }\n    gain.gain.setValueAtTime(volume, audioCtx.currentTime);\n    gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + duration);\n\n    osc.connect(gain);\n    gain.connect(audioCtx.destination);\n    osc.start();\n    osc.stop(audioCtx.currentTime + duration);\n  } catch (_) {}\n}\n\nfunction sfxEat() {\n  playTone(840, 1280, 0.08, 'sine', 0.09);\n}\n\nfunction sfxBotDeath() {\n  playTone(280, 70, 0.28, 'triangle', 0.12);\n}\n\nfunction sfxPlayerDeath() {\n  playTone(180, 40, 0.75, 'sawtooth', 0.16);\n}\n\nfunction toggleMute() {\n  isMuted = !isMuted;\n  localStorage.setItem('neonSerpents_muted', isMuted ? '1' : '0');\n  if (muteBtnEl) muteBtnEl.textContent = isMuted ? '🔇' : '🔊';\n  if (ambientGain && audioCtx) {\n    ambientGain.gain.setValueAtTime(isMuted ? 0 : 0.035, audioCtx.currentTime);\n  }\n}\n\n// ============================================================\n// §4  TOROIDAL WRAP & PERSISTENCE\n// ============================================================\n\nfunction wrap(val, max) {\n  return ((val % max) + max) % max;\n}\n\n/** Robust shortest toroidal delta across seams */\nfunction toroidDelta(a, b, size) {\n  let d = wrap(b, size) - wrap(a, size);\n  if (d > size * 0.5) d -= size;\n  else if (d < -size * 0.5) d += size;\n  return d;\n}\n\nfunction toroidDistSq(x1, y1, x2, y2) {\n  const dx = toroidDelta(x1, x2, width);\n  const dy = toroidDelta(y1, y2, height);\n  return dx * dx + dy * dy;\n}\n\nfunction angleDifference(current, target) {\n  return Math.atan2(Math.sin(target - current), Math.cos(target - current));\n}\n\nfunction interpolateColor(hex1, hex2, factor) {\n  const c1 = parseInt(hex1.slice(1), 16);\n  const c2 = parseInt(hex2.slice(1), 16);\n\n  const r1 = (c1 >> 16) & 255, g1 = (c1 >> 8) & 255, b1 = c1 & 255;\n  const r2 = (c2 >> 16) & 255, g2 = (c2 >> 8) & 255, b2 = c2 & 255;\n\n  const r = Math.round(r1 + factor * (r2 - r1));\n  const g = Math.round(g1 + factor * (g2 - g1));\n  const b = Math.round(b1 + factor * (b2 - b1));\n\n  return `rgb(${r}, ${g}, ${b})`;\n}\n\nfunction mixRgb(a, b, amount) {\n  return `rgb(${Math.round(a[0] + (b[0] - a[0]) * amount)}, ${Math.round(a[1] + (b[1] - a[1]) * amount)}, ${Math.round(a[2] + (b[2] - a[2]) * amount)})`;\n}\n\nfunction updateDayNightCycle(now = performance.now()) {\n  const cycleProgress = ((now - cycleEpoch) % CYCLE_DURATION_MS) / CYCLE_DURATION_MS;\n  const phasePosition = cycleProgress * CYCLE_PHASES.length;\n  const phaseIndex = Math.floor(phasePosition);\n  const from = CYCLE_PHASES[phaseIndex];\n  const to = CYCLE_PHASES[(phaseIndex + 1) % CYCLE_PHASES.length];\n  const linear = phasePosition - phaseIndex;\n  const blend = linear * linear * (3 - 2 * linear);\n  const lerp = (a, b) => a + (b - a) * blend;\n  const color = (a, b) => mixRgb(a, b, blend);\n\n  currentCycle.name = from.name;\n  currentCycle.icon = from.icon;\n  currentCycle.top = color(from.top, to.top);\n  currentCycle.mid = color(from.mid, to.mid);\n  currentCycle.bottom = color(from.bot, to.bot);\n  const ray = from.ray.map((component, index) => Math.round(lerp(component, to.ray[index])));\n  currentCycle.rayColor = `rgba(${ray[0]}, ${ray[1]}, ${ray[2]}, ${lerp(from.rays, to.rays).toFixed(3)})`;\n  currentCycle.rayStrength = lerp(from.rays, to.rays);\n  currentCycle.glow = lerp(from.glow, to.glow);\n  currentCycle.plankton = lerp(from.plankton, to.plankton);\n  currentCycle.nightFactor = lerp(from.name === 'Night' ? 1 : 0, to.name === 'Night' ? 1 : 0);\n  currentCycle.progress = cycleProgress;\n\n  if (cycleIconEl && cycleIconEl.textContent !== currentCycle.icon) cycleIconEl.textContent = currentCycle.icon;\n  if (cycleNameEl && cycleNameEl.textContent !== currentCycle.name) cycleNameEl.textContent = currentCycle.name;\n}\n\nfunction initPlankton() {\n  plankton.length = 0;\n  for (let i = 0; i < 20; i++) {\n    plankton.push({\n      x: Math.random() * width,\n      y: Math.random() * height,\n      size: 0.7 + Math.random() * 1.1,\n      drift: 0.08 + Math.random() * 0.18,\n      phase: Math.random() * Math.PI * 2\n    });\n  }\n}\n\nfunction updatePlankton() {\n  for (const dot of plankton) {\n    dot.y -= dot.drift;\n    if (dot.y < -4) {\n      dot.y = height + 4;\n      dot.x = Math.random() * width;\n    }\n  }\n}\n\nfunction formatTime(seconds) {\n  const m = Math.floor(seconds / 60).toString().padStart(2, '0');\n  const s = (seconds % 60).toString().padStart(2, '0');\n  return `${m}:${s}`;\n}\n\nfunction getBestTime(diff) {\n  return parseInt(localStorage.getItem(`neonSerpents_bestTime_${diff}`) || '0', 10);\n}\n\nfunction getBestLength(diff) {\n  return parseInt(localStorage.getItem(`neonSerpents_bestLength_${diff}`) || `${INITIAL_SEGMENTS}`, 10);\n}\n\nfunction saveBestRecords(diff, time, len) {\n  const curBestTime = getBestTime(diff);\n  const curBestLen = getBestLength(diff);\n  if (time > curBestTime) localStorage.setItem(`neonSerpents_bestTime_${diff}`, time.toString());\n  if (len > curBestLen) localStorage.setItem(`neonSerpents_bestLength_${diff}`, len.toString());\n}\n\nfunction updateMenuRecordsDisplay() {\n  const diff = currentDifficulty;\n  const bTime = getBestTime(diff);\n  const bLen = getBestLength(diff);\n  const capitalized = diff.charAt(0).toUpperCase() + diff.slice(1);\n  if (diffNameLabel) diffNameLabel.textContent = capitalized;\n  if (menuBestTime) menuBestTime.textContent = formatTime(bTime);\n  if (menuBestLen) menuBestLen.textContent = bLen;\n  if (cardDiffLabel) cardDiffLabel.textContent = capitalized;\n}\n\n// ============================================================\n// §5  BACKGROUND, FOOD & PARTICLES\n// ============================================================\n\nfunction isFarFromAllSnakes(x, y, minDist = 60) {\n  const minDistSq = minDist * minDist;\n  const allSnakes = [player, ...bots];\n  for (const s of allSnakes) {\n    if (!s.alive) continue;\n    if (toroidDistSq(s.x, s.y, x, y) < minDistSq) return false;\n    for (let i = 0; i < s.segments.length; i += 3) {\n      if (toroidDistSq(s.segments[i].x, s.segments[i].y, x, y) < minDistSq) return false;\n    }\n  }\n  return true;\n}\n\nfunction spawnFoodOrb(customX, customY, customColor) {\n  let x = customX !== undefined ? customX : Math.random() * width;\n  let y = customY !== undefined ? customY : Math.random() * height;\n\n  if (customX === undefined) {\n    for (let attempt = 0; attempt < 25; attempt++) {\n      if (isFarFromAllSnakes(x, y, 45)) break;\n      x = Math.random() * width;\n      y = Math.random() * height;\n    }\n  }\n\n  const scheme = customColor || FOOD_COLORS[Math.floor(Math.random() * FOOD_COLORS.length)];\n  return {\n    x,\n    y,\n    baseRadius: 4.5 + Math.random() * 2,\n    color: scheme.core,\n    glow: scheme.glow,\n    pulseSpeed: 0.04 + Math.random() * 0.04,\n    pulsePhase: Math.random() * Math.PI * 2,\n    vx: (Math.random() - 0.5) * 0.25,\n    vy: (Math.random() - 0.5) * 0.25,\n  };\n}\n\nfunction initFood() {\n  foodOrbs.length = 0;\n  for (let i = 0; i < FOOD_COUNT; i++) {\n    foodOrbs.push(spawnFoodOrb());\n  }\n}\n\nfunction updateFood() {\n  for (const orb of foodOrbs) {\n    orb.x = wrap(orb.x + orb.vx, width);\n    orb.y = wrap(orb.y + orb.vy, height);\n  }\n  while (foodOrbs.length < FOOD_COUNT) {\n    foodOrbs.push(spawnFoodOrb());\n  }\n}\n\nfunction spawnFoodBurst(x, y, color, count = 10) {\n  if (particles.length > MAX_PARTICLES) return;\n  for (let i = 0; i < count; i++) {\n    const angle = Math.random() * Math.PI * 2;\n    const speed = 1.2 + Math.random() * 3.2;\n    particles.push({\n      x,\n      y,\n      vx: Math.cos(angle) * speed,\n      vy: Math.sin(angle) * speed,\n      size: 2 + Math.random() * 2.5,\n      alpha: 1,\n      color,\n      decay: 0.03 + Math.random() * 0.02\n    });\n  }\n}\n\nfunction updateParticles() {\n  for (let i = particles.length - 1; i >= 0; i--) {\n    const p = particles[i];\n    p.x = wrap(p.x + p.vx, width);\n    p.y = wrap(p.y + p.vy, height);\n    p.vx *= 0.94;\n    p.vy *= 0.94;\n    p.alpha -= p.decay;\n    if (p.alpha <= 0) particles.splice(i, 1);\n  }\n\n}\n\n// ============================================================\n// §6  BOTS CREATION & BEHAVIOR (WITH ANTI-SPIN LOGIC)\n// ============================================================\n\nfunction getActiveSpeed() {\n  return SPEED_CONFIGS[currentDifficulty] || SPEED_CONFIGS.normal;\n}\n\nfunction findSafeSpawnCoords() {\n  let bestX = Math.random() * width;\n  let bestY = Math.random() * height;\n  let maxMinDistSq = -1;\n\n  const allSnakes = [player, ...bots];\n  for (let attempt = 0; attempt < 40; attempt++) {\n    const cx = Math.random() * width;\n    const cy = Math.random() * height;\n    let closestDistSq = Infinity;\n\n    for (const s of allSnakes) {\n      if (!s.alive) continue;\n      const dSq = toroidDistSq(cx, cy, s.x, s.y);\n      if (dSq < closestDistSq) closestDistSq = dSq;\n    }\n\n    if (closestDistSq > 90 * 90) {\n      return { x: cx, y: cy };\n    }\n    if (closestDistSq > maxMinDistSq) {\n      maxMinDistSq = closestDistSq;\n      bestX = cx;\n      bestY = cy;\n    }\n  }\n  return { x: bestX, y: bestY };\n}\n\nfunction createBot(config, index) {\n  const pos = findSafeSpawnCoords();\n  const initialAngle = Math.random() * Math.PI * 2;\n  const initialLength = INITIAL_SEGMENTS - 5 + Math.floor(Math.random() * 12);\n  const segments = [];\n\n  for (let i = 0; i < initialLength; i++) {\n    segments.push({\n      x: pos.x,\n      y: pos.y + i * SEGMENT_SPACING,\n      angle: initialAngle,\n      lateralOffset: 0\n    });\n  }\n\n  return {\n    name: config.name,\n    isPlayer: false,\n    x: pos.x,\n    y: pos.y,\n    angle: initialAngle,\n    targetAngle: initialAngle,\n    speed: getActiveSpeed() * (0.95 + Math.random() * 0.1),\n    turnRate: TURN_RATE * (0.9 + Math.random() * 0.2),\n    length: initialLength,\n    segments,\n    palette: config.palette,\n    tongueTimer: Math.floor(Math.random() * 150),\n    tongueProgress: 0,\n    growQueue: 0,\n    glowTrailTimer: 0,\n    alive: true,\n    respawnTimer: 0,\n    sameTurnCount: 0, // Anti-spin watchdog\n    personality: {\n      aggressiveness: 0.2 + Math.random() * 0.5,\n      lookAheadDist: 50 + Math.random() * 30\n    }\n  };\n}\n\nfunction initBots() {\n  bots.length = 0;\n  for (let i = 0; i < BOT_COUNT; i++) {\n    bots.push(createBot(BOT_CONFIGS[i], i));\n  }\n}\n\nfunction respawnBot(bot) {\n  const pos = findSafeSpawnCoords();\n  bot.x = pos.x;\n  bot.y = pos.y;\n  bot.angle = Math.random() * Math.PI * 2;\n  bot.targetAngle = bot.angle;\n  bot.speed = getActiveSpeed() * (0.95 + Math.random() * 0.1);\n  bot.length = INITIAL_SEGMENTS - 5 + Math.floor(Math.random() * 8);\n  bot.segments = [];\n  bot.growQueue = 0;\n  bot.glowTrailTimer = 0;\n  bot.alive = true;\n  bot.respawnTimer = 0;\n  bot.sameTurnCount = 0;\n\n  for (let i = 0; i < bot.length; i++) {\n    bot.segments.push({\n      x: pos.x,\n      y: pos.y + i * SEGMENT_SPACING,\n      angle: bot.angle,\n      lateralOffset: 0\n    });\n  }\n}\n\nfunction updateBotAI(bot) {\n  if (!bot.alive) return;\n\n  const allSnakes = [player, ...bots];\n\n  // 1. Food targeting\n  let nearestFood = null;\n  let nearestDistSq = Infinity;\n  for (const orb of foodOrbs) {\n    const dSq = toroidDistSq(bot.x, bot.y, orb.x, orb.y);\n    if (dSq < nearestDistSq) {\n      nearestDistSq = dSq;\n      nearestFood = orb;\n    }\n  }\n\n  let desiredAngle = bot.angle;\n  if (nearestFood) {\n    const dx = toroidDelta(bot.x, nearestFood.x, width);\n    const dy = toroidDelta(bot.y, nearestFood.y, height);\n    desiredAngle = Math.atan2(dy, dx);\n  }\n\n  // 2. Trapping / cutting off other snakes\n  if (player.alive && Math.random() < bot.personality.aggressiveness) {\n    const dToPlayerSq = toroidDistSq(bot.x, bot.y, player.x, player.y);\n    if (dToPlayerSq < 180 * 180 && dToPlayerSq > 50 * 50) {\n      const leadDist = 50;\n      const leadX = wrap(player.x + Math.cos(player.angle) * leadDist, width);\n      const leadY = wrap(player.y + Math.sin(player.angle) * leadDist, height);\n      const cdx = toroidDelta(bot.x, leadX, width);\n      const cdy = toroidDelta(bot.y, leadY, height);\n      desiredAngle = Math.atan2(cdy, cdx);\n    }\n  }\n\n  // 3. Obstacle avoidance (with anti-spin check)\n  const lookDist = bot.personality.lookAheadDist;\n  const sensorAngles = [0, 0.45, -0.45, 0.9, -0.9, 1.4, -1.4];\n  let bestDanger = 0;\n  let avoidTurn = 0;\n\n  for (const sa of sensorAngles) {\n    const checkAngle = bot.angle + sa;\n    const probeX = wrap(bot.x + Math.cos(checkAngle) * lookDist, width);\n    const probeY = wrap(bot.y + Math.sin(checkAngle) * lookDist, height);\n\n    let probeDanger = 0;\n    for (const other of allSnakes) {\n      if (!other.alive) continue;\n      const startSeg = (other === bot) ? 6 : 0;\n      for (let i = startSeg; i < other.segments.length; i += 2) {\n        const seg = other.segments[i];\n        const distSq = toroidDistSq(probeX, probeY, seg.x, seg.y);\n        const dangerRadius = HEAD_RADIUS + 10;\n        if (distSq < dangerRadius * dangerRadius) {\n          probeDanger += 1 / (1 + Math.sqrt(distSq));\n        }\n      }\n    }\n\n    if (probeDanger > 0) {\n      avoidTurn += (sa === 0 ? (Math.random() > 0.5 ? 1.5 : -1.5) : -Math.sign(sa) * 1.8);\n      bestDanger += probeDanger;\n    }\n  }\n\n  if (bestDanger > 0) {\n    bot.targetAngle = bot.angle + avoidTurn;\n  } else {\n    bot.targetAngle = desiredAngle + (Math.random() - 0.5) * 0.15;\n  }\n\n  // Anti-spin watchdog: if turning in the same direction for > 85 frames, unstick\n  const diff = angleDifference(bot.angle, bot.targetAngle);\n  if (Math.abs(diff) > 0.05) {\n    bot.sameTurnCount++;\n    if (bot.sameTurnCount > 85) {\n      bot.targetAngle = bot.angle + Math.PI * 0.7; // Break spin loop\n      bot.sameTurnCount = 0;\n    }\n  } else {\n    bot.sameTurnCount = Math.max(0, bot.sameTurnCount - 2);\n  }\n\n  bot.angle += Math.sign(diff) * Math.min(Math.abs(diff), bot.turnRate);\n}\n\n// ============================================================\n// §7  PHYSICS & UPDATE\n// ============================================================\n\nfunction advanceSnake(snake) {\n  if (!snake.alive) return;\n\n  snake.x = wrap(snake.x + Math.cos(snake.angle) * snake.speed, width);\n  snake.y = wrap(snake.y + Math.sin(snake.angle) * snake.speed, height);\n\n  snake.tongueTimer++;\n  if (snake.tongueTimer > 180) {\n    snake.tongueProgress = Math.sin(((snake.tongueTimer - 180) / 25) * Math.PI);\n    if (snake.tongueTimer >= 205) {\n      snake.tongueTimer = 0;\n      snake.tongueProgress = 0;\n    }\n  }\n\n  if (snake.growQueue > 0 && snake.segments.length > 0) {\n    const tail = snake.segments[snake.segments.length - 1];\n    snake.segments.push({\n      x: tail.x,\n      y: tail.y,\n      angle: tail.angle,\n      lateralOffset: 0\n    });\n    snake.growQueue--;\n  }\n\n  let prevX = snake.x;\n  let prevY = snake.y;\n\n  for (let i = 0; i < snake.segments.length; i++) {\n    const seg = snake.segments[i];\n    const dx = toroidDelta(seg.x, prevX, width);\n    const dy = toroidDelta(seg.y, prevY, height);\n    const dist = Math.hypot(dx, dy);\n\n    if (dist > SEGMENT_SPACING) {\n      const segAngle = Math.atan2(dy, dx);\n      seg.angle = segAngle;\n      seg.x = wrap(prevX - Math.cos(segAngle) * SEGMENT_SPACING, width);\n      seg.y = wrap(prevY - Math.sin(segAngle) * SEGMENT_SPACING, height);\n    }\n\n    const waveProgress = i / snake.segments.length;\n    const waveAmp = Math.sin(waveProgress * Math.PI) * 4.5;\n    seg.lateralOffset = Math.sin(animFrame * 0.14 - i * 0.32) * waveAmp;\n\n    prevX = seg.x;\n    prevY = seg.y;\n  }\n}\n\nfunction dissolveSnakeIntoFood(snake) {\n  for (let i = 0; i < snake.segments.length; i += 6) {\n    const seg = snake.segments[i];\n    const foodScheme = {\n      core: snake.palette.head,\n      glow: snake.palette.glow\n    };\n    foodOrbs.push(spawnFoodOrb(seg.x, seg.y, foodScheme));\n    spawnFoodBurst(seg.x, seg.y, snake.palette.head, 1);\n  }\n  spawnFoodBurst(snake.x, snake.y, snake.palette.head, 6);\n}\n\nfunction killBot(bot) {\n  if (!bot.alive) return;\n  bot.alive = false;\n  bot.respawnTimer = RESPAWN_DELAY_FRAMES;\n  dissolveSnakeIntoFood(bot);\n  sfxBotDeath();\n}\n\nfunction handlePlayerDeath() {\n  if (!player.alive || isGameOver) return;\n  player.alive = false;\n  isGameOver = true;\n  shakeIntensity = 18;\n\n  dissolveSnakeIntoFood(player);\n  sfxPlayerDeath();\n\n  saveBestRecords(currentDifficulty, survivalSeconds, player.length);\n  const bestT = getBestTime(currentDifficulty);\n  const bestL = getBestLength(currentDifficulty);\n\n  finalTimeEl.textContent = formatTime(survivalSeconds);\n  bestTimeEl.textContent = formatTime(bestT);\n  finalLengthEl.textContent = player.length;\n  bestLengthEl.textContent = bestL;\n  if (cardDiffLabel) {\n    cardDiffLabel.textContent = currentDifficulty.charAt(0).toUpperCase() + currentDifficulty.slice(1);\n  }\n  overlayEl.style.display = 'flex';\n}\n\nfunction checkAllCollisions() {\n  const allSnakes = [player, ...bots];\n\n  for (const snake of allSnakes) {\n    if (!snake.alive) continue;\n\n    for (const other of allSnakes) {\n      if (!other.alive || other === snake) continue;\n\n      for (let i = 0; i < other.segments.length; i++) {\n        const seg = other.segments[i];\n        const progress = i / other.segments.length;\n        const segRadius = Math.max(3.5, HEAD_RADIUS * (1 - progress * 0.72));\n        const hitRadius = (HEAD_RADIUS * 0.75) + (segRadius * 0.8);\n\n        if (toroidDistSq(snake.x, snake.y, seg.x, seg.y) < hitRadius * hitRadius) {\n          if (snake.isPlayer) {\n            handlePlayerDeath();\n          } else {\n            killBot(snake);\n          }\n          break;\n        }\n      }\n      if (!snake.alive) break;\n    }\n  }\n}\n\nfunction checkFoodConsumptionAll() {\n  const allSnakes = [player, ...bots];\n  const eatDistSq = (HEAD_RADIUS + 8) * (HEAD_RADIUS + 8);\n\n  for (const snake of allSnakes) {\n    if (!snake.alive) continue;\n\n    for (let i = foodOrbs.length - 1; i >= 0; i--) {\n      const orb = foodOrbs[i];\n      if (toroidDistSq(snake.x, snake.y, orb.x, orb.y) < eatDistSq) {\n        spawnFoodBurst(orb.x, orb.y, orb.color, 2);\n        foodOrbs.splice(i, 1);\n\n        snake.growQueue++;\n        snake.length++;\n\n        if (snake.isPlayer) {\n          sfxEat();\n          if (statLengthEl) statLengthEl.textContent = snake.length;\n        }\n      }\n    }\n  }\n}\n\nfunction updateHUDAndLeaderboard() {\n  if (!isGameOver) {\n    const elapsedMs = performance.now() - gameStartTime - totalPausedDuration;\n    survivalSeconds = Math.max(0, Math.floor(elapsedMs / 1000));\n    if (statTimeEl) statTimeEl.textContent = formatTime(survivalSeconds);\n  }\n\n  const allSnakes = [player, ...bots];\n  allSnakes.sort((a, b) => b.length - a.length);\n\n  const playerRank = allSnakes.findIndex(s => s.isPlayer) + 1;\n  if (statRankEl) statRankEl.textContent = `#${playerRank}`;\n\n  if (lbListEl) {\n    lbListEl.innerHTML = allSnakes.map((s, idx) => `\n      <div class=\"lb-item ${s.isPlayer ? 'is-player' : ''}\">\n        <div class=\"lb-left\">\n          <span class=\"lb-dot\" style=\"background:${s.palette.head}; box-shadow: 0 0 6px ${s.palette.glow}\"></span>\n          <span>${idx + 1}. ${s.name}</span>\n        </div>\n        <span class=\"lb-length\">${s.length}</span>\n      </div>\n    `).join('');\n  }\n}\n\nfunction update() {\n  if (!isGameRunning || isPaused) return;\n\n  animFrame++;\n\n  if (player.alive) {\n    if (keys.left) {\n      player.targetAngle -= player.turnRate;\n      mouse.active = false;\n    } else if (keys.right) {\n      player.targetAngle += player.turnRate;\n      mouse.active = false;\n    } else if (mouse.active) {\n      const dx = toroidDelta(player.x, mouse.x, width);\n      const dy = toroidDelta(player.y, mouse.y, height);\n      if (Math.hypot(dx, dy) > 15) {\n        player.targetAngle = Math.atan2(dy, dx);\n      }\n    }\n    const diff = angleDifference(player.angle, player.targetAngle);\n    player.angle += Math.sign(diff) * Math.min(Math.abs(diff), player.turnRate);\n  }\n\n  advanceSnake(player);\n\n  for (const bot of bots) {\n    if (!bot.alive) {\n      bot.respawnTimer--;\n      if (bot.respawnTimer <= 0) {\n        respawnBot(bot);\n      }\n      continue;\n    }\n    updateBotAI(bot);\n    advanceSnake(bot);\n  }\n\n  checkAllCollisions();\n  checkFoodConsumptionAll();\n\n  updateFood();\n  updateParticles();\n  updatePlankton();\n  updateHUDAndLeaderboard();\n\n  if (shakeIntensity > 0) {\n    shakeIntensity *= 0.9;\n    if (shakeIntensity < 0.2) shakeIntensity = 0;\n  }\n}\n\n// ============================================================\n// §8  MENU, DIFFICULTY & PAUSE\n// ============================================================\n\nfunction setDifficulty(diff) {\n  currentDifficulty = diff;\n  document.querySelectorAll('.diff-btn').forEach(btn => {\n    btn.classList.toggle('active', btn.dataset.diff === diff);\n  });\n  updateMenuRecordsDisplay();\n}\n\nfunction applyDifficultySpeeds() {\n  const spd = getActiveSpeed();\n  player.speed = spd;\n  for (const bot of bots) {\n    bot.speed = spd * (0.95 + Math.random() * 0.1);\n  }\n}\n\nfunction startGame() {\n  initAudio();\n  menuScreenEl.style.display = 'none';\n  hudEl.style.display = 'flex';\n  lbEl.style.display = 'block';\n  isGameRunning = true;\n  isPaused = false;\n  totalPausedDuration = 0;\n\n  initSnake();\n  initBots();\n  applyDifficultySpeeds();\n  ensureGameLoop();\n}\n\nfunction goHome() {\n  isGameRunning = false;\n  isPaused = false;\n  isGameOver = false;\n  keys.left = false;\n  keys.right = false;\n  mouse.active = false;\n  pauseOverlayEl.style.display = 'none';\n  overlayEl.style.display = 'none';\n  hudEl.style.display = 'none';\n  lbEl.style.display = 'none';\n  menuScreenEl.style.display = 'flex';\n  updateMenuRecordsDisplay();\n}\n\nwindow.handleAndroidBack = function () {\n  if (isGameRunning || isPaused || isGameOver) {\n    goHome();\n    return true;\n  }\n  return false;\n};\n\nfunction togglePause() {\n  if (!isGameRunning || isGameOver) return;\n  isPaused = !isPaused;\n  if (isPaused) {\n    pauseStartTime = performance.now();\n    pauseOverlayEl.style.display = 'flex';\n  } else {\n    totalPausedDuration += performance.now() - pauseStartTime;\n    pauseOverlayEl.style.display = 'none';\n    ensureGameLoop();\n  }\n}\n\nfunction initInput() {\n  window.addEventListener('resize', onResize);\n\n  const pauseButton = document.getElementById('pause-btn');\n  const homeButton = document.getElementById('home-btn');\n  pauseButton.addEventListener('pointerdown', (e) => e.stopPropagation());\n  pauseButton.addEventListener('touchstart', (e) => e.stopPropagation(), { passive: true });\n  pauseButton.addEventListener('click', (e) => {\n    e.stopPropagation();\n    togglePause();\n  });\n  homeButton.addEventListener('pointerdown', (e) => e.stopPropagation());\n  homeButton.addEventListener('click', (e) => { e.stopPropagation(); goHome(); });\n\n  document.addEventListener('visibilitychange', () => {\n    if (document.hidden && isGameRunning && !isPaused && !isGameOver) togglePause();\n  });\n\n  window.addEventListener('keydown', (e) => {\n    initAudio();\n    if (e.key === 'p' || e.key === 'P' || e.key === ' ') {\n      if (isGameRunning && !isGameOver) {\n        e.preventDefault();\n        togglePause();\n        return;\n      }\n    }\n\n    if (isGameOver) {\n      if (e.key === 'Enter') restartGame();\n      return;\n    }\n\n    if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') keys.left = true;\n    if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') keys.right = true;\n  });\n\n  window.addEventListener('keyup', (e) => {\n    if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') keys.left = false;\n    if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') keys.right = false;\n  });\n\n  window.addEventListener('mousemove', (e) => {\n    mouse.x = e.clientX;\n    mouse.y = e.clientY;\n    mouse.active = true;\n  });\n\n  window.addEventListener('touchstart', onTouch, { passive: true });\n  window.addEventListener('touchmove', onTouch, { passive: true });\n  window.addEventListener('touchend', () => { mouse.active = false; }, { passive: true });\n\n  overlayEl.addEventListener('click', () => {\n    if (isGameOver) restartGame();\n  });\n\n  pauseOverlayEl.addEventListener('click', () => {\n    if (isPaused) togglePause();\n  });\n}\n\nfunction onTouch(e) {\n  initAudio();\n  if (isPaused) {\n    togglePause();\n    return;\n  }\n  if (isGameOver) {\n    restartGame();\n    return;\n  }\n  if (e.touches.length > 0) {\n    mouse.x = e.touches[0].clientX;\n    mouse.y = e.touches[0].clientY;\n    mouse.active = true;\n  }\n}\n\nfunction onResize() {\n  width = window.innerWidth;\n  height = window.innerHeight;\n  const pixelRatio = Math.min(window.devicePixelRatio || 1, 1.25);\n  canvas.width = Math.round(width * pixelRatio);\n  canvas.height = Math.round(height * pixelRatio);\n  canvas.style.width = `${width}px`;\n  canvas.style.height = `${height}px`;\n  ctx.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);\n}\n\nfunction initSnake() {\n  player.x = width / 2;\n  player.y = height / 2;\n  player.angle = -Math.PI / 2;\n  player.targetAngle = -Math.PI / 2;\n  player.length = INITIAL_SEGMENTS;\n  player.speed = getActiveSpeed();\n  player.growQueue = 0;\n  player.segments = [];\n  player.alive = true;\n  \n  for (let i = 0; i < player.length; i++) {\n    player.segments.push({\n      x: player.x,\n      y: player.y + i * SEGMENT_SPACING,\n      angle: player.angle,\n      lateralOffset: 0\n    });\n  }\n\n  gameStartTime = performance.now();\n  totalPausedDuration = 0;\n  isGameOver = false;\n  overlayEl.style.display = 'none';\n  pauseOverlayEl.style.display = 'none';\n\n  if (statLengthEl) statLengthEl.textContent = player.length;\n  if (statRankEl) statRankEl.textContent = '#1';\n}\n\nfunction restartGame() {\n  overlayEl.style.display = 'none';\n  pauseOverlayEl.style.display = 'none';\n  isPaused = false;\n  initSnake();\n  initBots();\n  applyDifficultySpeeds();\n  ensureGameLoop();\n}\n\n// ============================================================\n// §9  RENDER: BACKGROUND, TRAIL, FOOD & SERPENTS\n// ============================================================\n\nfunction renderBackground() {\n  const bg = ctx.createLinearGradient(0, 0, 0, height);\n  bg.addColorStop(0, currentCycle.top);\n  bg.addColorStop(0.5, currentCycle.mid);\n  bg.addColorStop(1, currentCycle.bottom);\n  ctx.fillStyle = bg;\n  ctx.fillRect(0, 0, width, height);\n\n  if (currentCycle.rayStrength > 0.005) {\n    ctx.save();\n    ctx.globalCompositeOperation = 'screen';\n    ctx.globalAlpha = Math.min(0.85, currentCycle.rayStrength * 4.2);\n    for (let i = 0; i < 3; i++) {\n      const sway = Math.sin(animFrame * 0.006 + i * 1.9) * 18;\n      const x = width * (0.16 + i * 0.34) + sway;\n      const ray = ctx.createLinearGradient(x, 0, x + 80, height);\n      ray.addColorStop(0, currentCycle.rayColor);\n      ray.addColorStop(1, 'rgba(255,255,255,0)');\n      ctx.fillStyle = ray;\n      ctx.beginPath();\n      ctx.moveTo(x - 25, 0);\n      ctx.lineTo(x + 22, 0);\n      ctx.lineTo(x + 125, height);\n      ctx.lineTo(x + 30, height);\n      ctx.closePath();\n      ctx.fill();\n    }\n    ctx.restore();\n  }\n\n  const planktonAlpha = currentCycle.plankton;\n  if (planktonAlpha > 0.005) {\n    for (const dot of plankton) {\n      const twinkle = 0.72 + Math.sin(animFrame * 0.035 + dot.phase) * 0.28;\n      ctx.globalAlpha = planktonAlpha * twinkle;\n      ctx.fillStyle = '#9cf8df';\n      ctx.beginPath();\n      ctx.arc(dot.x, dot.y, dot.size, 0, Math.PI * 2);\n      ctx.fill();\n    }\n    ctx.globalAlpha = 1;\n  }\n}\n\nfunction renderFood() {\n  for (const orb of foodOrbs) {\n    const radius = Math.max(2, orb.baseRadius * 0.72);\n    ctx.shadowColor = orb.glow;\n    ctx.shadowBlur = 2 + currentCycle.nightFactor * 12;\n    ctx.fillStyle = orb.color;\n    ctx.beginPath();\n    ctx.arc(orb.x, orb.y, radius, 0, Math.PI * 2);\n    ctx.fill();\n  }\n  ctx.shadowBlur = 0;\n}\n\nfunction renderParticles() {\n  for (const p of particles) {\n    ctx.save();\n    ctx.globalAlpha = p.alpha;\n    ctx.fillStyle = p.color;\n    ctx.beginPath();\n    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);\n    ctx.fill();\n    ctx.restore();\n  }\n}\n\nfunction drawDiamondScale(cx, cy, radius, angle, color) {\n  ctx.save();\n  ctx.translate(cx, cy);\n  ctx.rotate(angle);\n  ctx.beginPath();\n  ctx.moveTo(0, -radius * 0.7);\n  ctx.lineTo(radius * 0.6, 0);\n  ctx.lineTo(0, radius * 0.7);\n  ctx.lineTo(-radius * 0.6, 0);\n  ctx.closePath();\n  ctx.fillStyle = color;\n  ctx.fill();\n  ctx.restore();\n}\n\nfunction drawNameTag(name, x, y, color) {\n  ctx.save();\n  ctx.font = 'bold 11px system-ui, sans-serif';\n  const textWidth = ctx.measureText(name).width;\n  const paddingX = 8;\n  const tagHeight = 18;\n  const tagWidth = textWidth + paddingX * 2;\n  const tagY = y - 26;\n\n  ctx.fillStyle = 'rgba(2, 6, 23, 0.75)';\n  ctx.strokeStyle = color;\n  ctx.lineWidth = 1;\n  ctx.beginPath();\n  ctx.roundRect(x - tagWidth / 2, tagY, tagWidth, tagHeight, 9);\n  ctx.fill();\n  ctx.stroke();\n\n  ctx.fillStyle = '#f8fafc';\n  ctx.textAlign = 'center';\n  ctx.textBaseline = 'middle';\n  ctx.fillText(name, x, tagY + tagHeight / 2);\n  ctx.restore();\n}\n\nfunction drawRealisticSnakeAt(snake, offsetX, offsetY) {\n  if (!snake.alive) return;\n  const segs = snake.segments;\n  if (segs.length === 0) return;\n\n  ctx.save();\n  ctx.translate(offsetX, offsetY);\n\n  const pal = snake.palette;\n\n  // Tongue\n  if (snake.tongueProgress > 0) {\n    const tLen = snake.tongueProgress * 16;\n    const hx = snake.x + Math.cos(snake.angle) * HEAD_RADIUS;\n    const hy = snake.y + Math.sin(snake.angle) * HEAD_RADIUS;\n    const tx = hx + Math.cos(snake.angle) * tLen;\n    const ty = hy + Math.sin(snake.angle) * tLen;\n\n    const forkAngle = 0.45;\n    const forkLen = 5 * snake.tongueProgress;\n    const f1x = tx + Math.cos(snake.angle + forkAngle) * forkLen;\n    const f1y = ty + Math.sin(snake.angle + forkAngle) * forkLen;\n    const f2x = tx + Math.cos(snake.angle - forkAngle) * forkLen;\n    const f2y = ty + Math.sin(snake.angle - forkAngle) * forkLen;\n\n    ctx.strokeStyle = pal.tongue;\n    ctx.lineWidth = 1.8;\n    ctx.lineCap = 'round';\n    ctx.beginPath();\n    ctx.moveTo(hx, hy);\n    ctx.lineTo(tx, ty);\n    ctx.lineTo(f1x, f1y);\n    ctx.moveTo(tx, ty);\n    ctx.lineTo(f2x, f2y);\n    ctx.stroke();\n  }\n\n  // Body segments\n  for (let i = segs.length - 1; i >= 0; i--) {\n    const seg = segs[i];\n    const progress = i / segs.length;\n    let radius = Math.max(3.5, HEAD_RADIUS * (1 - progress * 0.72));\n\n    const perpAngle = seg.angle + Math.PI / 2;\n    const drawX = seg.x + Math.cos(perpAngle) * seg.lateralOffset;\n    const drawY = seg.y + Math.sin(perpAngle) * seg.lateralOffset;\n\n    const segColor = interpolateColor(pal.bodyStart, pal.bodyEnd, progress);\n\n    ctx.beginPath();\n    ctx.arc(drawX, drawY, radius, 0, Math.PI * 2);\n    ctx.fillStyle = segColor;\n    ctx.shadowColor = pal.glow;\n    ctx.shadowBlur = i % 6 === 0 ? currentCycle.nightFactor * 5 : 0;\n    ctx.fill();\n\n    if (i % 2 === 0 && radius > 5) {\n      drawDiamondScale(drawX, drawY, radius * 0.75, seg.angle, pal.scale);\n    }\n  }\n\n  ctx.shadowColor = pal.glow;\n  ctx.shadowBlur = 3 + currentCycle.nightFactor * 18;\n\n  // Head\n  ctx.save();\n  ctx.translate(snake.x, snake.y);\n  ctx.rotate(snake.angle);\n\n  ctx.beginPath();\n  ctx.ellipse(2, 0, HEAD_RADIUS + 1, HEAD_RADIUS - 1.5, 0, 0, Math.PI * 2);\n  ctx.fillStyle = pal.head;\n  ctx.fill();\n\n  ctx.shadowBlur = 0;\n\n  ctx.beginPath();\n  ctx.ellipse(5, 0, HEAD_RADIUS * 0.45, HEAD_RADIUS * 0.35, 0, 0, Math.PI * 2);\n  ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';\n  ctx.fill();\n\n  // Eyes\n  const eyeX = 3;\n  const eyeY = 6.2;\n  const eyeRadius = 3.6;\n  const pupilRadius = 1.6;\n\n  [-eyeY, eyeY].forEach((ey) => {\n    ctx.beginPath();\n    ctx.arc(eyeX, ey, eyeRadius, 0, Math.PI * 2);\n    ctx.fillStyle = '#ffffff';\n    ctx.fill();\n\n    ctx.beginPath();\n    ctx.arc(eyeX + 0.8, ey, eyeRadius * 0.65, 0, Math.PI * 2);\n    ctx.fillStyle = pal.eyeIris;\n    ctx.fill();\n\n    ctx.beginPath();\n    ctx.arc(eyeX + 1.2, ey, pupilRadius, 0, Math.PI * 2);\n    ctx.fillStyle = pal.eyePupil;\n    ctx.fill();\n\n    ctx.beginPath();\n    ctx.arc(eyeX + 0.5, ey - 1, 0.8, 0, Math.PI * 2);\n    ctx.fillStyle = '#ffffff';\n    ctx.fill();\n  });\n\n  ctx.restore();\n\n  drawNameTag(snake.name, snake.x, snake.y, pal.head);\n\n  ctx.restore();\n}\n\n/** Optimized Toroidal Drawing: Only draws clones when spanning an edge */\nfunction drawSnakeToroidal(snake) {\n  if (!snake.alive) return;\n\n  // Always draw primary instance\n  drawRealisticSnakeAt(snake, 0, 0);\n\n  // Check if near boundaries (within head radius + tail reach)\n  const margin = HEAD_RADIUS * 2 + 15;\n  const nearLeft = snake.x < margin;\n  const nearRight = snake.x > width - margin;\n  const nearTop = snake.y < margin;\n  const nearBottom = snake.y > height - margin;\n\n  if (nearLeft) drawRealisticSnakeAt(snake, width, 0);\n  if (nearRight) drawRealisticSnakeAt(snake, -width, 0);\n  if (nearTop) drawRealisticSnakeAt(snake, 0, height);\n  if (nearBottom) drawRealisticSnakeAt(snake, 0, -height);\n\n  if (nearLeft && nearTop) drawRealisticSnakeAt(snake, width, height);\n  if (nearLeft && nearBottom) drawRealisticSnakeAt(snake, width, -height);\n  if (nearRight && nearTop) drawRealisticSnakeAt(snake, -width, height);\n  if (nearRight && nearBottom) drawRealisticSnakeAt(snake, -width, -height);\n}\n\nfunction render() {\n  updateDayNightCycle();\n  ctx.save();\n  if (shakeIntensity > 0) {\n    const sx = (Math.random() - 0.5) * shakeIntensity;\n    const sy = (Math.random() - 0.5) * shakeIntensity;\n    ctx.translate(sx, sy);\n  }\n\n  renderBackground();\n  renderFood();\n  renderParticles();\n\n  for (const bot of bots) {\n    drawSnakeToroidal(bot);\n  }\n\n  drawSnakeToroidal(player);\n\n  ctx.restore();\n}\n\n// ============================================================\n// §10  LOOP & STARTUP\n// ============================================================\nfunction gameLoop() {\n  if (!isGameRunning || isPaused || isGameOver) {\n    loopActive = false;\n    return;\n  }\n  update();\n  render();\n  requestAnimationFrame(gameLoop);\n}\n\nfunction ensureGameLoop() {\n  if (loopActive) return;\n  loopActive = true;\n  requestAnimationFrame(gameLoop);\n}\n\nwindow.addEventListener('DOMContentLoaded', () => {\n  canvas = document.getElementById('game-canvas');\n  ctx = canvas.getContext('2d');\n  hudEl = document.getElementById('hud');\n  lbEl = document.getElementById('leaderboard');\n  menuScreenEl = document.getElementById('menu-screen');\n  pauseOverlayEl = document.getElementById('pause-overlay');\n  statTimeEl = document.getElementById('stat-time');\n  statLengthEl = document.getElementById('stat-length');\n  statRankEl = document.getElementById('stat-rank');\n  lbListEl = document.getElementById('lb-list');\n  overlayEl = document.getElementById('overlay');\n  finalTimeEl = document.getElementById('final-time');\n  bestTimeEl = document.getElementById('best-time');\n  finalLengthEl = document.getElementById('final-length');\n  bestLengthEl = document.getElementById('best-length');\n  muteBtnEl = document.getElementById('mute-btn');\n  diffNameLabel = document.getElementById('diff-name-label');\n  menuBestTime = document.getElementById('menu-best-time');\n  menuBestLen = document.getElementById('menu-best-len');\n  cardDiffLabel = document.getElementById('card-diff-label');\n  cycleIconEl = document.getElementById('cycle-icon');\n  cycleNameEl = document.getElementById('cycle-name');\n\n  isMuted = localStorage.getItem('neonSerpents_muted') === '1';\n  if (muteBtnEl) muteBtnEl.textContent = isMuted ? '🔇' : '🔊';\n\n  onResize();\n  initPlankton();\n  initFood();\n  initInput();\n  initBots();\n  updateMenuRecordsDisplay();\n});\n</script>\n</body>\n</html>\n";
export const PRIVACY_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#111827\">\n  <title>Privacy Policy — Serpent Run</title>\n  <style>\n    :root { color-scheme: dark; font-family: system-ui, sans-serif; background: #111827; color: #f3f4f6; }\n    body { max-width: 760px; margin: 0 auto; padding: 32px 20px; line-height: 1.65; }\n    h1, h2 { color: #f9fafb; }\n    a { color: #a7f3d0; }\n  </style>\n</head>\n<body>\n  <main>\n    <h1>Privacy Policy for Serpent Run</h1>\n    <p>Last updated: November 2, 2026</p>\n    <p>Serpent Run is an offline game published by Muneeb. This policy explains what the app stores and how it is handled.</p>\n\n    <h2>Information and storage</h2>\n    <p>The game does not require an account and does not collect or transmit personal information. It saves your best survival time, best length, and sound preference on your device using local browser storage. This information stays on your device, is not sent to the developer, and is not shared with third parties. Uninstalling the app or clearing its storage removes these records.</p>\n\n    <h2>Permissions, advertising, and analytics</h2>\n    <p>The game does not request sensitive device permissions and does not include advertising, analytics, or third-party tracking SDKs.</p>\n\n    <h2>Children</h2>\n    <p>The game does not knowingly collect personal information from children or other users.</p>\n\n    <h2>Changes and contact</h2>\n    <p>This policy may be updated when the app's data practices change. For privacy questions, contact the developer using the support contact shown on the Serpent Run Google Play listing.</p>\n  </main>\n</body>\n</html>\n";
